mapper.select:
select t.tx_id, t.inventory_id, t.sku_id, t.warehouse_code, t.tx_type, t.quantity,
       t.before_qty, t.after_qty, t.biz_type, t.biz_no, t.operator_id, t.create_time, t.remark,
       s.sku_code
from inventory_transaction t
left join product_sku s on s.sku_id = t.sku_id

    and t.sku_id = #{skuId}
    and t.warehouse_code = #{warehouseCode}
    and t.tx_type = #{txType}
    and t.biz_no = #{bizNo}

order by t.tx_id desc
